import{_ as a,C as e,c,o as p,aa as i,G as d}from"./chunks/framework.Cn7WEiMX.js";const w=JSON.parse('{"title":"通过 dmap 命令配置世界与地图","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/Dynmap/setup/guides/using-dmap.md","filePath":"wiki/Dynmap/setup/guides/using-dmap.md"}'),s={name:"wiki/Dynmap/setup/guides/using-dmap.md"};function m(g,t,r,n,u,_){const l=e("NolebaseGitContributors"),o=e("NolebaseGitChangelog");return p(),c("div",null,[t[0]||(t[0]=i('<h1 id="通过-dmap-命令配置世界与地图" tabindex="-1">通过 dmap 命令配置世界与地图 <a class="header-anchor" href="#通过-dmap-命令配置世界与地图" aria-label="Permalink to &quot;通过 dmap 命令配置世界与地图&quot;">​</a></h1> <p>在 0.31 之后的版本，Dynmap 新增了配置命令，便于管理员或控制台通过命令调整世界与地图。使用任意命令后，现存配置会转移进 <code>worlds.txt</code> 文件（无论现有地图是否基于 <code>worlds.txt</code> 或默认模板）。新增世界仍使用模板，但只要配置转移到 <code>worlds.txt</code> 后，之后模板的变动不会同步到这些世界中。另外，地图编辑命令仅限 HDMaps 使用——旧版的 KzedMap 与 FlatMap 不能用 <code>/dmap</code> 命令设置。</p> <p>需要注意的是，不可以在渲染任务进行时使用 <code>/dmap</code> 编辑命令（所有除 <code>/dmap worldlist</code>、<code>/dmap maplist</code>、<code>/dmap perspectivelist</code>、<code>/dmap shaderlist</code> 与 <code>/dmap lightinglist</code> 之外的命令）。所以，为了开始使用，必须先输入 <code>/dynmap pause all</code> 命令，暂停所有完整渲染及更新渲染任务——不要忘记在完成后使用 <code>/dynmap pause none</code> 命令解除暂停，否则会导致任务停止，进而导致后台日志堆积，内存使用量飙升。</p> <p>停止渲染后，<code>/dmap</code> 命令就可以用于添加、删除、渲染或修改现有的地图定义。世界列表设置的顺序也可以自行决定。如下为命令可实现的功能示例：</p> <ul><li>禁用/隐藏世界：<code>/dmap worldset &lt;世界名称&gt; enabled:false</code></li> <li>保护世界，通过权限管理插件限制为仅浏览：<code>/dmap mapset &lt;世界名称&gt;:&lt;地图名称&gt; protected:true</code></li> <li>重置世界与地图设置，使用默认模板：<code>/dmap worldreset &lt;世界名称&gt;</code></li> <li>重置世界与地图设置，使用特定模板（替换现有所有地图）：<code>/dmap worldreset &lt;世界名称&gt; &lt;模板名称&gt;</code></li> <li>置顶世界：<code>/dmap worldset &lt;世界名称&gt; order:1</code></li> <li>修改世界标题：<code>/dmap worldset &lt;世界名称&gt; title:&lt;&quot;标题文本&quot;&gt;</code></li> <li>隐藏指定世界的玩家位置与生命显示：<code>/dmap worldset &lt;世界名称&gt; sendposition:false sendhealth:false</code></li> <li>将世界中心位置移动到玩家当前位置：<code>/dmap worldset &lt;世界名称&gt; center:here</code></li> <li>将世界中心位置移动到指定位置：<code>/dmap worldset &lt;世界名称&gt; center:&lt;X&gt;/&lt;Y&gt;/&lt;Z&gt;</code></li> <li>将世界的额外缩放等级设置为 N：<code>/dmap worldset &lt;世界名称&gt; extrazoomout:&lt;N&gt;</code></li> <li>列出指定世界的地图：<code>/dmap maplist &lt;世界名称&gt;</code></li> <li>删除指定世界的地图：<code>/dmap mapdelete &lt;世界名称&gt;:&lt;地图名称&gt;</code></li> <li>向指定世界新增地图（带标题、角度、着色器及光照）：<code>/dmap mapadd &lt;世界名称&gt;:&lt;地图名称&gt; title:&lt;&quot;地图标题&quot;&gt; perspective:&lt;角度 ID&gt; shader:&lt;着色器 ID&gt; lighting:&lt;光照 ID&gt;</code></li> <li>将地图在世界中的顺序/位置改为 N：<code>/dmap mapset &lt;世界名称&gt;:&lt;地图名称&gt; order:&lt;N&gt;</code></li> <li>编辑地图标题：<code>/dmap mapset &lt;世界名称&gt;:&lt;地图名称&gt; title:&lt;&quot;地图标题&quot;&gt;</code></li> <li>修改地图角度（缩放或查看角度）：<code>/dmap mapset &lt;世界名称&gt;:&lt;地图名称&gt; perspective:&lt;角度 ID&gt;</code></li> <li>修改地图前缀：<code>/dmap mapset &lt;世界名称&gt;:&lt;地图名称&gt; prefix:&lt;前缀&gt;</code></li> <li>设置地图图标（相对于 <code>webpath</code> 的路径，如 <code>images/block_skylands.png</code>）：<code>/dmap mapset &lt;世界名称&gt;:&lt;地图名称&gt; icon:images/block_skylands.png</code></li> <li>将地图缩放等级设置为 N：<code>/dmap mapset &lt;世界名称&gt;:&lt;地图名称&gt; mapzoomin:&lt;N&gt;</code></li> <li>修改地图图块存储格式为 JPG：<code>/dmap mapset &lt;世界名称&gt;:&lt;地图名称&gt; img-format:jpg</code></li> <li>修改默认洞穴地图，使其使用新“纹理洞穴景观”：<code>/dmap mapset &lt;世界名称&gt;:&lt;地图名称&gt; shader:stdtexture-cave</code></li> <li>保护世界，只允许有权限玩家浏览：<code>/dmap mapset &lt;世界名称&gt;:&lt;地图名称&gt; protected:true</code></li> <li>浏览可用角度：<code>/dmap perspectivelist</code></li> <li>浏览可用着色器：<code>/dmap shaderlist</code></li> <li>浏览可用光照：<code>/dmap lightinglist</code></li> <li>设置地图与其他世界的地图一同出现：<code>/dmap mapset &lt;世界名称&gt;:&lt;地图名称&gt; append-to-world:&lt;另一世界名称&gt;</code></li></ul> <div class="info custom-block"><p class="custom-block-title">注意</p> <p>通过 <code>mapset</code> 设置的属性也可以用 <code>mapadd</code> 对新地图设置。</p></div> <p>大部分编辑命令需要启动一次完整渲染才会生效。</p> <p>编辑完成后，记得输入 <code>/dynmap pause none</code> 解除暂停正常的渲染。</p> ',16)),d(l),d(o)])}const f=a(s,[["render",m]]);export{w as __pageData,f as default};
